Set-Location O:/repos.hobby/ntvdm64
try {
 foreach($arch in @('x86','x64')) {
  & tools/build/New-T310FirmwareResourceNinja.ps1 -Architecture $arch -RuntimeRoot O:/repos.hobby/ntvdm64/build/t483-s5-p113/candidate-final
  if($LASTEXITCODE){throw 'Generate failed'}
  & 'C:/Users/neko/AppData/Local/Microsoft/WinGet/Packages/BrechtSanders.WinLibs.POSIX.MSVCRT_Microsoft.Winget.Source_8wekyb3d8bbwe/mingw64/bin/ninja.exe' -C "build/M0-T310/S8/p1-firmware-resource/$arch" all-verify
  if($LASTEXITCODE){throw "Firmware/media/boot fixtures failed: $arch"}
  "PASS firmware/media/boot fixtures: $arch"
 }
